<?php
namespace App\Notifications;
use Illuminate\Bus\Queueable; use Illuminate\Notifications\Messages\MailMessage; use Illuminate\Notifications\Notification;
class AccountSetupNotification extends Notification { use Queueable; public function __construct(protected string $token, protected string $schoolName) {} public function via($notifiable):array{return ['mail','database'];} public function toMail($notifiable):MailMessage{$url=rtrim(config('app.frontend_url'),'/').'/reset-password?token='.urlencode($this->token).'&user_id='.$notifiable->id.'&setup=1'; return (new MailMessage)->subject("Set up your Skulag account — {$this->schoolName}")->greeting("Hello {$notifiable->name},")->line("Your Skulag account for {$this->schoolName} has been created.")->action('Set My Password',$url)->line('This link expires in 60 minutes and can only be used to set your password.')->salutation('— Skulag');} public function toArray($notifiable):array{return ['title'=>'Account setup','body'=>'Your account is ready. Check your email for the secure password setup link.'];}}
